const seen = new Set();
const output = [];
for (const [index, item] of $input.all().entries()) {
  const link = String(item.json.link ?? '').trim();
  const title = String(item.json.title ?? '').trim();
  const contentSnippet = String(item.json.contentSnippet ?? item.json.content ?? '').trim();
  if (!/^https?:\/\//i.test(link) || !title || !contentSnippet || seen.has(link)) continue;
  seen.add(link);
  output.push({ json: { ...item.json, link, title, contentSnippet }, pairedItem: { item: index } });
}
return output;

const responses = $input.all();
const sources = $('Prepare RSS').all();
if (responses.length !== sources.length) throw new Error('Quantidade inesperada de respostas da consulta de duplicidade.');
for (const item of responses) {
  if (item.json.success !== true || !Array.isArray(item.json.data)) {
    throw new Error('A consulta de duplicidade falhou ou retornou dados inválidos. Publicação interrompida.');
  }
}
for (let index = 0; index < responses.length; index++) {
  if (responses[index].json.data.length === 0) {
    return [{ json: sources[index].json, pairedItem: { item: index } }];
  }
}
return [];

const articles = $input.all();
const collection_started_at = $('Schedule Trigger1').first().json.timestamp;
const candidates = articles.flatMap(({json: item}, index) => {
  const url = typeof item.link === 'string' ? item.link.trim() : '';
  const title = typeof item.title === 'string' ? item.title.trim() : '';
  const text = [item.source_content, item['content:encoded'], item.content, item.contentSnippet].find(value => typeof value === 'string' && value.trim());
  if (!(url.startsWith('https://') || url.startsWith('http://')) || !title || !text) return [];
  return [{id:"mV87fV58QynLJvVR:" + (index + 1),editoria:"piaui",title:title.slice(0,500),url,text:text.trim().slice(0,16000)}];
}).slice(0,10);
return candidates.length ? [{json:{editorial_source:"Piauí | G1 | Diário do Povo",candidates,collection_started_at,publish_by_briefing:true}}] : [];

const items = $input.all();
const sources = $('Select First New').all();
if (items.length !== 1 || sources.length !== 1) throw new Error('É necessário processar exatamente uma notícia por execução.');
const rss = sources[0].json;
const raw = items[0].json.output;
const parsed = typeof raw === 'string'
  ? JSON.parse(raw.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, ''))
  : raw;
if (!parsed || Array.isArray(parsed) || typeof parsed !== 'object') throw new Error('Resposta da IA não é um objeto JSON.');
for (const field of ['title', 'hat', 'content', 'excerpt', 'tags']) {
  if (typeof parsed[field] !== 'string' || !parsed[field].trim()) throw new Error('Resposta da IA inválida: ' + field);
}
const content = parsed.content.replace(/\\[nr]/g, '').replace(/\r?\n/g, '').replace(/<\/?n>/gi, '').replace(/>\s+</g, '><').trim();
if (!/<p[\s>]/i.test(content) || !content.replace(/<[^>]*>/g, '').trim()) throw new Error('Conteúdo HTML vazio ou inválido.');
if (/<(?:script|iframe|object|embed)\b|\bon\w+\s*=/i.test(content)) throw new Error('Conteúdo HTML contém elementos não permitidos.');
if (parsed.title.trim().length > 500 || content.length > 1000000) throw new Error('Conteúdo excede os limites da API.');
const config = $('Config1').first().json;
return [{ json: { title: parsed.title.trim(), hat: parsed.hat.trim().toUpperCase().slice(0,60), content, excerpt: parsed.excerpt.trim().slice(0,160), original_link: rss.link, category_id: Number(config.DEFAULT_CATEGORY_ID), author_id: Number(config.DEFAULT_AUTHOR_ID), status: 'draft' }, pairedItem: { item: 0 } }];

const response = $input.first().json;
if (response.success !== true || !Array.isArray(response.data)) throw new Error('Não foi possível confirmar a duplicidade antes da publicação.');
if (response.data.length > 0) return [];
return [{ json: $('Parse AI1').first().json, pairedItem: { item: 0 } }];

const sources = new Map($('Prepare RSS').all().map(({ json: source }) => [source.link, source]));
const result = [];
for (const [index, item] of $input.all().entries()) {
  const response = item.json;
  const draft = $('Confirm Still New').itemMatching(index).json;
  if (response.success === true && response.data?.reused === true) continue;
  if (response.success !== true || !Number.isSafeInteger(response.data?.id) || response.data.status !== 'draft' || response.data.reused !== false) {
    throw Error('O CMS não confirmou um novo rascunho para ' + draft.original_link);
  }
  const rss = sources.get(draft.original_link);
  const sourceText = rss && [rss.source_content, rss['content:encoded'], rss.content, rss.contentSnippet].find(value => typeof value === 'string' && value.trim());
  if (!sourceText || (response.data.original_link && response.data.original_link !== draft.original_link)) throw Error('Rascunho sem fonte correspondente: ' + draft.original_link);
  result.push({ json: { post_id: response.data.id, title: draft.title, content: draft.content, original_link: draft.original_link, sources: [{ id: "G1 Piauí", text: sourceText.trim().slice(0, 16000), url: draft.original_link }] }, pairedItem: { item: index } });
}
return result;
